nce(obj, dict):\n        for k, v in obj.items():\n            k_lower = str(k).lower()\n            if 'exchange' in k_lower or 'rate' in k_lower or 'pound' in k_lower or 'dollar' in k_lower or 'britain' in k_lower or 'sterling' in k_lower:\n                results.append((f'{path}.{k}', str(v)[:500]))\n            results.extend(find_exchange_rates(v, f'{path}.{k}'))\n    elif isinstance(obj, list):\n        for i, item in enumerate(obj):\n            results.extend(find_exchange_rates(item, f'{path}[{i}]'))\n    return results\n\nresults = find_exchange_rates(data)\nfor r in results[:20]:\n    print(f\"{r[0]}: {r[1][:200]}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
